def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    templates = []
    template_cells = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start >= 2:
                seq = row[start:c]
                templates.append(seq)
                template_cells.update((r, x) for x in range(start, c))
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == 0 or (r, c) in template_cells:
                continue
            seq = next((s for s in templates if color in s), None)
            if seq is None:
                continue
            start = c - seq.index(color)
            for i, value in enumerate(seq):
                x = start + i
                if 0 <= x < w:
                    out[r][x] = value
    return out

